import json,statistics as st,collections,shutil
from pathlib import Path
p=Path('/Users/sun/.loom/reviews/2026-10-23-page-performance')
xs=[json.loads(l) for l in (p/'results.jsonl').read_text().splitlines()]
def stats(v):return {'n':len(v),'median':round(st.median(v),2),'min':round(min(v),2),'max':round(max(v),2)}
loads={};samples=[]
for arm in ['before','after']:
 for cache in ['cold','warm']:
  z=[x for x in xs if x['kind']=='load' and x['sample'].startswith('run-') and x['arm']==arm and x['cache']==cache];assert len(z)==6
  loads[arm+'-'+cache]={'readyMs':stats([x['readyMs'] for x in z]),'transferBytes':stats([sum(r['transfer'] for r in x['resources']) for x in z]),'resourceCount':stats([len(x['resources']) for x in z])}
  for x in z:samples.append({'arm':arm,'cache':cache,'sample':x['sample'],'readyMs':x['readyMs'],'transferBytes':sum(r['transfer'] for r in x['resources']),'resources':len(x['resources']),'visibility':x['visibility']})
g=collections.defaultdict(list);counts=collections.Counter();clicks=[]
for x in xs:
 if x['kind']=='click' and x['sample'].startswith('click-'):
  k=(x['arm'],x['sample'],x['label']);cycle=counts[k];counts[k]+=1;assert cycle<2
  g[x['arm'],x['label'],cycle].append(x['duration']);clicks.append({k:x[k] for k in ['arm','sample','label','duration','visibility']}|{'cycle':cycle})
assert len(g)==24 and all(len(v)==6 for v in g.values())
clickStats={f'{a}/{l}/'+('first' if c==0 else 'repeat'):stats(v) for (a,l,c),v in g.items()}
r=json.loads((p/'restart.json').read_text());wire=json.loads((p/'wire.json').read_text())
summary={'implementation':'616be3db','baseline':'5f61d227 (deployed immutable web snapshot)','changes':['Shared HTTP/HTTPS gateway negotiates streaming gzip for finite JSON >=1024 bytes; SSE, ranges, no-transform, HEAD and already encoded responses excluded. Browser decodes original JSON; no schema/history/authority change.','Loom module demand loader retains exact official PanelFallback and native page components, immediately publishes resolved modules and retains nested Suspense handling; aborts late mounted-page state updates and propagates import failures.','Computer auto-selection checks actual current destination before using a render-captured router setter; stale callbacks cannot resurrect an old destination.'],'tests':{'redThenGreen':['API negotiation/content equivalence','page module resolution/unmount/failure','stale computer selection route reproduction'],'focusedPassed':23,'uiContractPassed':8,'rootTypecheck':'passed','frontendTypecheck':'passed','workbenchBuild':'passed'},'method':{'browser':'Existing Chrome, viewport 1440x1000, no network or CPU throttle','backend':'Same live Core/data both arms; identical controlled proxy/static gzip. Before arm serves previous immutable UI and requests identity API responses, matching previous API transport. After serves new UI and forwards encoding negotiation.','scope':'Local HTTP controlled comparison, not remote-device latency or Firefox full-page HTTPS','cold':'HTTP cache bypass (no-store), not new browser/JIT process','warm':'Primed static-resource cache, API remains no-store','ready':'composer and 54 message DOM elements, no alert, then two frames. Resources collected ready+400ms; transferSize excludes navigation document/probe.','click':'real captured click to visible target page plus two frames; measures presentation not all async data or INP. 6 paired journeys, each 6 pages and 2 cycles.','sampling':'24 alternating successful loads; 144 successful measured clicks; no exclusions, blocked API paths or failed journeys.','noDataMutation':'No messages, role configurations or CLI work created. Normal channel read acknowledgements allowed.'},'loadResults':loads,'clickResults':clickStats,'wireVerification':wire,'browserAcceptance':{'desktop':'Formal product switched Computers -> Tasks; nine task cards loaded. Same channel renders 54 message DOM nodes with no alert.','mobile':'390x844 formal task/Agent/chat pages visible; mobile Agent nav target 68.8x44, actual center hit true. No viewport emulation claimed as real-device acceptance.'},'deployment':{'pid':r['newPid'],'assets':r['newStaticDirectory'],'backup':r['backup'],'databases':r['databases'],'files':r['files'],'unchangedBusinessTables':len(r['businessTables']),'pushStateUnchanged':r['pushStateUnchanged'],'sourceHash':r['sourceSha256']},'limits':['First page presentation improved; full bootstrap ready time did not consistently improve. Cold median418->421ms, warm298->333ms, broad ranges overlap; do not claim startup acceleration.','Computer stale callback reproduced in isolated test; previous browser missed-navigation symptoms are compatible with it but not proven exclusively caused by it. Both arms had zero missed destinations in this repetition.','Compression reduces wire bytes, not decoded JSON/parse work, source data size or model tokens.','No authenticated live Raft comparator, Firefox timing, long-running stutter acceptance or physical mobile acceptance.','No paid CLI gates run.'],'conclusion':'First-open five-page median improved from327-334ms to34-61ms. Warm refresh resource transfer425305->78382 bytes (-81.57%); cold1885524->1538717 (-18.39%). Repeat navigation stays approximately21-37ms; startup latency not improved consistently.','rawLocalDirectory':str(p)}
out=Path('docs/evo/evidence/2026-10-23-page-performance');out.mkdir(exist_ok=True)
for f,d in [('summary.json',summary),('samples.json',{'loads':samples,'clicks':clicks})]:(out/f).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
for f in ['probe.js','server.mjs','verify-wire.mjs','summarize.py']:shutil.copyfile(p/f,out/f)
print('wrote',len(samples),'loads',len(clicks),'clicks')
